"""Force-field registry for the Hyp benchmark.

Rules enforced here (see tests/):
  * every parameter file is listed with origin + sha256 (results/provenance.json)
  * derived files (ff99SB HYP template, C36mGP CMAP scaling) are generated by code,
    never hand edited, and are flagged derived=True
  * a force field can only be combined with a solvent model on its allow-list
  * createSystem failures (missing parameters) propagate - nothing is substituted
"""
import hashlib
import json
import os
import re
import xml.etree.ElementTree as ET

import openmm.app as app

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OMM = os.path.join(os.path.dirname(app.__file__), "data")
OMFF = os.path.join(ROOT, "ff", "omff", "repo", "openmmforcefields", "ffxml", "charmm")
GMX = os.path.join(ROOT, "ff", "gromacs")
DERIVED = os.path.join(ROOT, "ff", "derived")

FF99_HYP_XML = os.path.join(DERIVED, "ff99SB_HYP_from_gromacs_rtp.xml")
C36MGP_XML = os.path.join(DERIVED, "charmm36mGP_protein_cmapGP_x0.5.xml")
C36M_HYP_XML = os.path.join(DERIVED, "charmm36m_HYP_only_from_d_modified.xml")
C36M_MODRES_SRC = os.path.join(OMFF, "charmm36_d_modified.xml")

# name -> definition
FORCEFIELDS = {
    "ff99SB": dict(
        family="amber",
        files=[os.path.join(OMM, "amber99sb.xml"), FF99_HYP_XML],
        water="tip3p",
        cite="Hornak 2006 (ff99SB); HYP residue as distributed in GROMACS amber99sb.ff",
        derived=True,
        derived_note="HYP template re-encoded from GROMACS amber99sb.ff/aminoacids.rtp into OpenMM XML "
                     "(OpenMM's amber99sb.xml has no HYP). Types/charges copied verbatim; bonded terms come "
                     "from the ff99SB class tables. Equivalence to GROMACS ffbonded.itp is unit-tested.",
    ),
    "ff14SB": dict(
        family="amber",
        files=[os.path.join(OMM, "amber14", "protein.ff14SB.xml")],
        water="tip3p",
        cite="Maier 2015; OpenMM conversion of AmberTools 17.6 leaprc.protein.ff14SB",
        derived=False,
    ),
    "ff19SB": dict(
        family="amber",
        files=[os.path.join(OMM, "amber19", "protein.ff19SB.xml")],
        water="opc",
        cite="Tian 2020; OpenMM conversion of AmberTools 24.8 leaprc.protein.ff19SB",
        derived=False,
    ),
    "C36m": dict(
        family="charmm",
        files=[os.path.join(OMM, "charmm36_2024.xml"), C36M_HYP_XML],
        water="charmm-tip3p",
        cite="Huang 2017; toppar_c36_jul24 conversions: OpenMM 8.6.1 charmm36_2024.xml (par_all36m_prot.prm) + "
             "HYP residue from openmmforcefields charmm36_d_modified.xml (toppar_all36_prot_modify_res.str)",
        derived=True,
        derived_note="HYP <Residue> element copied verbatim out of charmm36_d_modified.xml into its own file. "
                     "Loading the whole modified-residue file is not possible for peptides: it also defines "
                     "graph-identical DPRO, HZP (hydroxyproline with CGenFF atom types) and an AMGY patch, which "
                     "OpenMM cannot distinguish from PRO, HYP and ACE. No parameter values are changed; AllowPatch "
                     "references to patches defined only in that file (AMGY, DMCT) are dropped.",
    ),
    "C36mGP": dict(
        family="charmm",
        files=[C36MGP_XML, C36M_HYP_XML],
        water="charmm-tip3p",
        cite="Pantelopulos & Best 2025 definition applied to the C36m files above",
        derived=True,
        derived_note="RECONSTRUCTION: CMAP grids whose central C-alpha class is CT2 (Gly) or CP1 (Pro/Hyp) "
                     "multiplied by 0.5, per the published definition. The authors' own files "
                     "(Zenodo 10.5281/zenodo.15354101) could not be downloaded here and were NOT compared.",
    ),
}

WATER_FILES = {
    ("amber", "tip3p"): os.path.join(OMM, "amber14", "tip3p.xml"),
    ("amber", "opc"): os.path.join(OMM, "amber19", "opc.xml"),
    ("charmm", "charmm-tip3p"): os.path.join(OMM, "charmm36_2024", "water.xml"),
}

# solvent allow-list.  'validated' = pairing used in the FF's own validation or in the
# collagen benchmark (Pantelopulos & Best 2025); 'discouraged' = runs but developers advise against.
SOLVENT_POLICY = {
    "ff99SB": dict(validated=["tip3p"], discouraged=["opc"]),
    "ff14SB": dict(validated=["tip3p"], discouraged=["opc"]),
    "ff19SB": dict(validated=["opc"], discouraged=["tip3p"]),
    "C36m": dict(validated=["charmm-tip3p"], discouraged=[]),
    "C36mGP": dict(validated=["charmm-tip3p"], discouraged=[]),
}


class IncompatibleCombination(ValueError):
    pass


def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def check_pairing(ff, water, allow_discouraged=False):
    pol = SOLVENT_POLICY[ff]
    fam = FORCEFIELDS[ff]["family"]
    if water is None:
        return
    if (fam, water) not in WATER_FILES:
        raise IncompatibleCombination(f"{water} is not a {fam}-family water model; refusing to mix families")
    if water in pol["validated"]:
        return
    if water in pol["discouraged"] and allow_discouraged:
        return
    raise IncompatibleCombination(f"{ff} + {water} is not on the validated list {pol['validated']}")


def load(ff, water="default", allow_discouraged=False):
    """Return an openmm.app.ForceField.  water=None -> gas phase; 'default' -> FF's validated water."""
    d = FORCEFIELDS[ff]
    files = list(d["files"])
    for f in files:
        if not os.path.exists(f):
            raise FileNotFoundError(f"{f} missing - run scripts/01_prepare.py (no fallback is attempted)")
    if water == "default":
        water = d["water"]
    if water is not None:
        check_pairing(ff, water, allow_discouraged)
        files.append(WATER_FILES[(d["family"], water)])
    return app.ForceField(*files)


# ----------------------------------------------------------------------------- derived files
def _rtp_block(path, name):
    txt = open(path).read()
    m = re.search(r"^\[ %s \]\s*\n(.*?)(?=^\[ [A-Z0-9]+ \]\s*$)" % re.escape(name), txt, re.S | re.M)
    if not m:
        raise KeyError(f"[ {name} ] not found in {path}")
    sect, out = None, {"atoms": [], "bonds": [], "impropers": [], "cmap": []}
    for line in m.group(1).splitlines():
        line = line.split(";")[0].strip()
        if not line:
            continue
        s = re.match(r"\[ (\w+) \]", line)
        if s:
            sect = s.group(1)
            continue
        out.setdefault(sect, []).append(line.split())
    return out


def gromacs_hyp(ffdir):
    """HYP atoms [(name,type,charge)], bonds from a GROMACS .ff directory."""
    blk = _rtp_block(os.path.join(GMX, ffdir, "aminoacids.rtp"), "HYP")
    atoms = [(a[0], a[1], float(a[2])) for a in blk["atoms"]]
    return atoms, blk["bonds"], blk


# GROMACS amber99sb.ff HYP atom names -> PDB-style names used in this project
_GMX99_RENAME = {"CD2": "CD", "HD21": "HD22", "HD22": "HD23", "HB1": "HB2", "HB2": "HB3"}


def make_ff99sb_hyp_xml(out=FF99_HYP_XML):
    atoms, bonds, _ = gromacs_hyp("amber99sb.ff")
    base = ET.parse(os.path.join(OMM, "amber99sb.xml")).getroot()
    cls_of = {t.get("name"): t.attrib for t in base.find("AtomTypes")}
    # LJ per AMBER class taken from the ff99SB XML itself (must be unique per class)
    lj = {}
    for a in base.find("NonbondedForce").findall("Atom"):
        c = cls_of[a.get("type")]["class"]
        lj.setdefault(c, set()).add((a.get("sigma"), a.get("epsilon")))
    root = ET.Element("ForceField")
    info = ET.SubElement(root, "Info")
    ET.SubElement(info, "Source").text = (
        "GENERATED by hypbench.ffreg.make_ff99sb_hyp_xml from GROMACS share/top/amber99sb.ff/aminoacids.rtp "
        "[ HYP ] (sha256 %s). Not an AmberTools file." % sha256(os.path.join(GMX, "amber99sb.ff", "aminoacids.rtp")))
    at = ET.SubElement(root, "AtomTypes")
    res = ET.SubElement(ET.SubElement(root, "Residues"), "Residue", name="HYP")
    nb = ET.SubElement(root, "NonbondedForce", coulomb14scale="0.833333", lj14scale="0.5")
    masses = {}
    for t in base.find("AtomTypes"):
        masses.setdefault(t.get("class"), (t.get("element"), t.get("mass")))
    names = []
    for name, typ, q in atoms:
        name = _GMX99_RENAME.get(name, name)
        names.append(name)
        if typ not in lj or len(lj[typ]) != 1:
            raise RuntimeError(f"ambiguous or missing LJ for AMBER class {typ}: {lj.get(typ)}")
        el, mass = masses[typ]
        tn = f"HYP99-{name}"
        ET.SubElement(at, "Type", {"name": tn, "class": typ, "element": el, "mass": mass})
        ET.SubElement(res, "Atom", name=name, type=tn)
        sig, eps = next(iter(lj[typ]))
        ET.SubElement(nb, "Atom", type=tn, charge=repr(q), sigma=sig, epsilon=eps)
    for a, b in bonds:
        if a.startswith("-") or b.startswith("-") or a.startswith("+") or b.startswith("+"):
            continue
        a, b = _GMX99_RENAME.get(a, a), _GMX99_RENAME.get(b, b)
        ET.SubElement(res, "Bond", {"from": str(names.index(a)), "to": str(names.index(b))})
    ET.SubElement(res, "ExternalBond", {"from": str(names.index("N"))})
    ET.SubElement(res, "ExternalBond", {"from": str(names.index("C"))})
    os.makedirs(os.path.dirname(out), exist_ok=True)
    ET.indent(root)
    ET.ElementTree(root).write(out)
    return out


def make_c36m_hyp_xml(out=C36M_HYP_XML):
    src = ET.parse(C36M_MODRES_SRC).getroot()
    hyp = [r for r in src.find("Residues") if r.get("name") == "HYP"]
    if len(hyp) != 1:
        raise RuntimeError("expected exactly one HYP residue in the modified-residue file")
    root = ET.Element("ForceField")
    info = ET.SubElement(root, "Info")
    ET.SubElement(info, "Source").text = (
        "GENERATED by hypbench.ffreg.make_c36m_hyp_xml: verbatim copy of <Residue name='HYP'> from "
        f"openmmforcefields charmm36_d_modified.xml (sha256 {sha256(C36M_MODRES_SRC)}, toppar_c36_jul24).")
    base_patches = {p.get("name") for p in ET.parse(os.path.join(OMM, "charmm36_2024.xml")).getroot().find("Patches")}
    dropped = []
    for ap in hyp[0].findall("AllowPatch"):
        if ap.get("name") not in base_patches:  # patches that live only in the modified-residue file
            dropped.append(ap.get("name"))
            hyp[0].remove(ap)
    info[0].text += " AllowPatch references removed (patch not in charmm36_2024.xml): " + ", ".join(dropped)
    ET.SubElement(root, "Residues").append(hyp[0])
    os.makedirs(os.path.dirname(out), exist_ok=True)
    ET.ElementTree(root).write(out)
    return out


GP_CENTRAL_CLASSES = ("CT2", "CP1")  # Gly C-alpha; Pro/Hyp C-alpha in CHARMM36


def make_c36mgp_xml(out=C36MGP_XML, scale=0.5):
    src = os.path.join(OMM, "charmm36_2024.xml")
    tree = ET.parse(src)
    root = tree.getroot()
    cm = root.find("CMAPTorsionForce")
    maps = cm.findall("Map")
    tors = cm.findall("Torsion")
    log = []
    new_index = {}
    for t in tors:
        central = t.get("class3") or t.get("type3")
        if central in GP_CENTRAL_CLASSES:
            old = int(t.get("map"))
            if old not in new_index:
                vals = [float(x) * scale for x in maps[old].text.split()]
                m = ET.Element("Map")
                m.text = "\n" + " ".join(repr(v) for v in vals) + "\n"
                # insert new map elements before the first Torsion so indices stay = order of <Map>
                cm.insert(len(cm.findall("Map")), m)
                new_index[old] = len(cm.findall("Map")) - 1
            t.set("map", str(new_index[old]))
            log.append(dict(classes=[t.get(f"class{i}") for i in range(1, 6)], old_map=old, new_map=new_index[old]))
    info = root.find("Info")
    ET.SubElement(info, "Source").text = (
        f"GENERATED by hypbench.ffreg.make_c36mgp_xml: CMAP x{scale} for central classes {GP_CENTRAL_CLASSES}; "
        f"source sha256 {sha256(src)}. Reconstruction of CHARMM36mGP (Pantelopulos & Best 2025), not the authors' file.")
    os.makedirs(os.path.dirname(out), exist_ok=True)
    tree.write(out)
    return out, log


def provenance():
    rec = {}
    for name, d in FORCEFIELDS.items():
        w = WATER_FILES[(d["family"], d["water"])]
        rec[name] = dict(
            cite=d["cite"], derived=d["derived"], derived_note=d.get("derived_note"),
            files=[dict(path=os.path.relpath(f, ROOT) if f.startswith(ROOT) else f.replace(OMM, "<openmm-8.6.1>/app/data"),
                        sha256=sha256(f)) for f in d["files"] + [w]],
            default_water=d["water"],
        )
    return rec


if __name__ == "__main__":
    print(json.dumps(provenance(), indent=1))
